android.extraProguardRules:
-dontwarn org.webrtc.Dav1dDecoder$Natives
# Google's ads SDK brings WorkManager 2.7.0 and Room 2.2.5, whose database Room creates by name at
# startup; R8's full mode kept the class but dropped its constructor, and every launch crashed (D137).
-keep class androidx.work.impl.WorkDatabase_Impl { *; }
-keepclassmembers class * extends androidx.room.RoomDatabase { <init>(); }
